begin;
select no_plan();
insert into auth.users(id,aud,role,email,is_anonymous,raw_app_meta_data) select ('39000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','masterpeople'||n||'@test.local',false,'{"provider":"google"}'::jsonb from generate_series(1,28)n;
insert into public.platform_roles(user_id,role) select id,case when email='masterpeople28@test.local' then 'support' else 'master' end from auth.users where email like 'masterpeople%@test.local';
insert into public.events(id,title,category,host_id,host_name,duration_hours,capacity,shots_per_person,start_at) values('39000000-0000-4000-8000-000000000100','Agregação','festa','39000000-0000-4000-8000-000000000001','Organizador',6,10,10,now());
insert into public.payment_orders(event_id,host_id,plan_code,amount_cents,provider_env,idempotency_key,status) select '39000000-0000-4000-8000-000000000100','39000000-0000-4000-8000-000000000001','festa',2900,'production',gen_random_uuid(),'pago' from generate_series(1,501);
insert into public.platform_roles(user_id,role) values ('39000000-0000-4000-8000-000000000001','auditor');
select set_config('request.jwt.claims','{"sub":"39000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"master"}}',true);
set local role authenticated;
select is((public.admin_master_people('organizadores',25,0,null)#>>'{items,0,spentCents}')::bigint,1452900::bigint,'gasto inclui todos os 501 pedidos, sem limite de 500');
select is((public.admin_master_people('equipe',25,25,null)->>'total')::int,28,'equipe conta antes da paginação');
select is(jsonb_array_length(public.admin_master_people('equipe',25,25,null)->'items'),3,'última página da equipe acessível');
select is((public.admin_master_people('equipe',25,0,'masterpeople28@')->>'total')::int,1,'busca antes da paginação');
select is(jsonb_array_length(public.admin_master_people('equipe',999,0,null)->'items'),25,'limite máximo de 25');
select throws_ok($$select public.admin_master_people('inventada')$$,'MM005','invalid','aba fora do desenho recusada');
reset role;
select set_config('request.jwt.claims','{"sub":"39000000-0000-4000-8000-000000000028","role":"authenticated","app_metadata":{"role":"support"}}',true);
set local role authenticated;
select is(public.admin_master_people('organizadores',25,0,null)#>'{items,0,spentCents}','null'::jsonb,'support não recebe dados financeiros');
select is(public.admin_master_people('equipe',25,0,'39000000-0000-4000-8000-000000000001')#>>'{items,0,email}','m***@test.local','support recebe máscara');
select is((public.admin_master_people('equipe',25,0,'masterpeople1@test.local')->>'total')::int,0,'support não pesquisa email oculto');
reset role;
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.admin_master_people()$$,'MM004','forbidden','identidade sem papel recusada');
reset role;
select ok(not has_function_privilege('anon','public.admin_master_people(text,integer,integer,text)','execute'),'anon sem grant');
select ok(has_function_privilege('authenticated','public.admin_master_people(text,integer,integer,text)','execute'),'autenticado usa autorização interna');
select * from finish();
rollback;
